always_ff@(posedge clk or negedge resetN)
begin
	if(!resetN) begin
		RGBout <=	8'h00;
		HitEdgeCode <= 3'h0;
	end

	else begin
		RGBout <= TRANSPARENT_ENCODING ; // default  
		HitEdgeCode <= 3'h0;

		if (InsideRectangle == 1'b1 ) 
		begin // inside an external bracket 
			case(inputDirection)
				8: RGBout <= object_colors[OBJECT_HEIGHT_Y- 1 - offsetY][OBJECT_HEIGHT_Y- 1 - offsetX];
				6: RGBout <= object_colors[offsetY][offsetX];
				4: RGBout <= object_colors[offsetY][OBJECT_HEIGHT_Y- 1 - offsetX];
				2: RGBout <= object_colors[OBJECT_HEIGHT_Y- 1 - offsetY][OBJECT_HEIGHT_Y- 1 - offsetX];
				default: RGBout <= object_colors[offsetY][offsetX];
			endcase
			//HitEdgeCode <= hit_colors[HitCodeY][HitCodeX];	//get hitting edge code from the colors table  
		
		end  	
	end
		
end

assign drawingRequest = (RGBout != TRANSPARENT_ENCODING ) ? 1'b1 : 1'b0 ;

